import collections,html,json
from pathlib import Path
P=Path(__file__).resolve().parent;D=json.loads((P/'selection.json').read_text());I=json.loads((P/'inputs.json').read_text());S=D['summary']
def e(s):return html.escape(str(s))
def n(x,d=0):return f'{x:,.{d}f}'.replace(',','\u202f').replace('.',',')
def rub(x,d=0):return n(x,d)+' ₽'
def pct(x):return n(x*100,1)+'%'
def tab(headers,rows):return '<div class="table"><table><thead><tr>'+''.join('<th>'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def ingredients(r,exclude_base=False):
 items=r['current_recipe']['direct_items'];items=[x for x in items if not(exclude_base and (x['name']=='Нори' or x['name'].startswith('Рис для роллов')))]
 return '; '.join(e(' '.join(x['name'].split()))+' '+n(x['display_amount'],0 if float(x['display_amount']).is_integer() else 1)+' '+e(x['display_unit']) for x in items)
labels={'cold':'Холодные','baked':'Запечённые','fried':'Жареные'}
sections=[];cards=[]
for cat,rolls in D['groups'].items():
 sumq=sum(r['sales']['paid_qty'] for r in rolls);sumR=sum(r['sales']['revenue'] for r in rolls)
 rows=[]
 for r in rolls:
  s=r['sales'];C=r['current_costing'];fc=r['current_recipe_repriced_period_fc_with_zero_net'];cls='hot' if fc>.33 else ''
  rows.append([str(r['rank']),'<a href="#r-'+r['roll_guid']+'">'+e(r['name'])+'</a>',n(s['paid_qty'])+'<br><span class="small">'+n(s.get('in_set_paid_qty',0))+' в сетах</span>',pct(r['share_roll_revenue']),'<span class="small">'+ingredients(r,True)+'</span>',rub(C['priced_food_cost_ex_water_rub'],2),'<strong class="'+cls+'">'+pct(fc)+'</strong>','<span class="small">'+pct(r['historical_period_fc_with_zero_net'])+'</span>'])
  ingredientrows=[[e(x['name']),n(x['display_amount'],0 if float(x['display_amount']).is_integer() else 2)+' '+e(x['display_unit'])] for x in r['current_recipe']['direct_items']]
  leafrows=[]
  for x in C['leaves']:
   amount=n(x['grams_if_kg'],3)+' г' if x['grams_if_kg'] is not None else n(x['quantity_per_portion'],5)+' '+e(x['unit'])
   leafrows.append([e(x['name']),amount,'Не определена' if x['unit_price_rub'] is None else rub(x['unit_price_rub'],2)+'/'+e(x['unit']),e(x['price_date'] or '—'),'Не оценена' if x['cost_rub'] is None else rub(x['cost_rub'],3)])
  mon=[]
  for m,q in r['months'].items():
   mon.append([{'2026-07':'Июль','2026-08':'Август','2026-09':'Сентябрь'}[m],n(q.get('standalone_paid_qty',0)),n(q.get('in_set_paid_qty',0)),n(q.get('zero_net_qty',0)),rub(q.get('revenue',0)),pct(q['food']/q['revenue']) if q.get('revenue',0)>0 else '—'])
  catalog=r['current_recipe'];price=C['current_iiko_default_sale_price_rub'];pricestr=rub(price) if price>0 else 'Отдельной цены нет (0 в каталоге)'
  catalogfc=pct(C['food_cost_percent_at_iiko_default_price_ex_water']/100) if C['food_cost_percent_at_iiko_default_price_ex_water'] is not None else 'Не определяется'
  cards.append('<article class="recipe" id="r-'+r['roll_guid']+'"><h3>'+e(r['name'])+'</h3><p class="small">'+labels[cat]+' · GUID '+r['roll_guid']+' · версия карты '+e(catalog['date_from'])+' · чтение 19.10.2026. Единица выхода — порция.</p>'+tab(['Закладка на порцию (сверка API)','Количество'],ingredientrows)+'<p>Сырьё по закупкам на 19.10: <strong>'+rub(C['priced_food_cost_ex_water_rub'],2)+'</strong>, вода отдельно '+n(C['water_l_per_portion'],4)+' л без подтверждённой закупочной цены. Упаковка в этих картах не найдена; общая упаковка и прочие расходы не превращаются в ноль.</p><p>FC при пересчёте на выпуск периода с нулевыми порциями: <strong>'+pct(fc)+'</strong>; только оплаченные порции: '+pct(r['current_recipe_repriced_period_fc_paid_only'])+'. Исторический учётный FC: '+pct(r['historical_period_fc_with_zero_net'])+'.</p><p class="small">Базовая цена <strong>каталога iiko</strong>: '+pricestr+'; FC к ней до скидок: '+catalogfc+'. Это не подтверждение текущей цены клиентской витрины. Статус самостоятельного базового меню: '+('включён' if catalog['defaultIncludedInMenu_raw'] else 'не включён; компонент сетов')+'.</p>'+tab(['Месяц','Отдельно, оплачено','В сетах, оплачено','Нулевая оплата','Выручка, распределена','FC исторический'],mon)+'<details><summary>Полное сырьевое разложение и закупочные цены</summary>'+tab(['Сырьё','На порцию','Последняя цена','Дата закупки','Стоимость'],leafrows)+'</details></article>')
 sections.append('<section><h2>'+labels[cat]+' — 10 позиций</h2><p class="small">'+n(sumq)+' оплаченных порций · '+rub(sumR)+' распределённой выручки · '+pct(sumR/S['all_roll_revenue'])+' выручки всех роллов.</p>'+tab(['№','Ролл','Продажи, порций','Доля выручки роллов','Начинка и добавки сейчас¹','Сырьё сейчас²','FC пересчёт³','FC учётный⁴'],rows)+'</section>')
rawcontrols=[[m,n(c['raw_net'],2),n(c['roll_net_allocated'],2),n(c['roll_food_allocated'],2),n(c['paid_roll_qty']),n(c['zero_net_roll_qty'])] for m,c in D['source_controls'].items()]
notes=''.join('<li>'+e(x)+'</li>' for x in D['quality_notes'])
# Nested prepared-card quantities already normalized to one base unit of prepared product.
pfs=[]
for x in I['recipes']['expanded_nodes'].values():
 if x['product_type']!='PREPARED':continue
 pfs.append('<details><summary>'+e(x['name'])+' — на 1 '+e(x['unit'])+' заготовки</summary>'+tab(['Компонент','Закладка'],[[e(z['name']),n(z['display_amount'],3)+' '+e(z['display_unit'])] for z in x['direct_items']])+'<p class="small">Версия '+e(x['date_from'])+'; закладки не равны готовому весу. '+e(x.get('technology',''))+'</p></details>')
body='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Тепло — 30 роллов для проработки</title><style>
:root{--ink:#17372f;--muted:#536d65;--green:#187259;--line:#d9e4dc;color-scheme:light}*{box-sizing:border-box}body{margin:0;background:#f5f6f1;color:var(--ink);font:15px/1.52 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1500px;margin:auto;padding:38px 26px 80px}h1{font-size:37px;line-height:1.14;letter-spacing:-1px;margin:12px 0 18px}h2{font-size:25px;margin:32px 0 14px}h3{font-size:22px;margin:5px 0 12px}p{margin:10px 0}.eyebrow{font-size:12px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase;color:var(--green)}.lead{font-size:18px;max-width:1060px;color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:25px 0}.card{background:white;border:1px solid var(--line);border-radius:14px;padding:20px}.card strong{display:block;font-size:30px;color:var(--green)}.small{font-size:13px;color:var(--muted)}.note{background:#e7eee4;padding:17px 20px;border-left:4px solid var(--green);border-radius:0 8px 8px 0;margin:20px 0}.attention{background:#fff1d8;border-color:#c18c22}.table{overflow-x:auto;background:white;border:1px solid var(--line);border-radius:10px}table{border-collapse:collapse;width:100%;font-size:14px}th{text-align:left;background:#e9efe6;color:#38574a}td,th{padding:10px 11px;vertical-align:top;border-bottom:1px solid var(--line)}tr:last-child td{border-bottom:0}td{font-variant-numeric:tabular-nums}td:nth-child(5){min-width:240px}a{color:var(--green)}.hot{color:#a14922}.recipe{background:white;padding:24px;border:1px solid var(--line);border-radius:14px;margin:20px 0;scroll-margin-top:15px}.recipe .table{max-width:1200px}details{margin:14px 0}summary{cursor:pointer;font-weight:650}li{margin:8px 0}.nav{display:flex;gap:15px;flex-wrap:wrap}small{color:var(--muted)}@media(max-width:780px){main{padding:22px 13px}h1{font-size:29px}.cards{grid-template-columns:1fr}.recipe{padding:15px}th,td{padding:8px}td:nth-child(5){min-width:170px}}
</style><main>'''
body+='<div class="eyebrow">Тепло · Черникова · июль–сентябрь 2026 · карты и закупки 19 октября</div><h1>30 популярных роллов для проработки</h1><p class="lead">По 10 холодных, запечённых и жареных. Рейтинг — по количеству оплаченных физических порций, включая компоненты платных сетов. Нулевые и подарочные выдачи показаны отдельно и не поднимают позицию в рейтинге.</p>'
body+='<div class="cards"><div class="card">Отобрано оплаченных порций<strong>'+n(S['selected_paid_portions'])+'</strong><span class="small">'+pct(S['selected_paid_coverage'])+' всего оплаченного выпуска роллов</span></div><div class="card">Доля выручки роллов<strong>'+pct(S['selected_roll_revenue_coverage'])+'</strong><span class="small">'+rub(S['selected_revenue'])+' из '+rub(S['all_roll_revenue'])+'</span></div><div class="card">Доля выручки предприятия<strong>'+pct(S['selected_enterprise_revenue_coverage'])+'</strong><span class="small">Чистая выручка предприятия '+rub(S['enterprise_revenue'])+'</span></div></div>'
body+='<div class="note"><strong>Два FC разделены.</strong> FC учётный — себестоимость продаж июля–сентября. FC пересчёт — сколько стоили бы эти же порции по сегодняшним картам и последним закупочным ценам при той же оплаченной выручке. Это сравнение на прежнем составе скидок и сетов, а не измеренный FC продаж октября.</div>'
body+='<p><strong>91,21% оплаченных порций выборки приходится на сеты:</strong> '+n(S['selected_paid_in_sets'])+' в сетах и '+n(S['selected_paid_standalone'])+' отдельно. При изменении рецептур пересчитываем стоимость самих сетов. Дополнительно у выбранных SKU было '+n(S['selected_zero_net_portions'])+' порций с нулевой оплатой: их текущая стоимость включена в FC пересчёта.</p>'
body+='<p class="nav"><a href="#tables">Три десятки</a><a href="#recipes">Карты с граммовками</a><a href="#prepared">Составы заготовок</a><a href="#methods">Метод и проверки</a></p><div id="tables"></div>'+''.join(sections)
body+='<p class="small">¹ В сводке — начинка и добавки. Рис, нори, кляр и панировка полностью показаны в картах ниже. Все закладки на порцию; это не измеренный готовый вес. ² Сырьё без отдельной цены воды, до труда, доставки и других расходов. ³ Текущая стоимость × весь выпуск SKU, включая нулевой, / распределённая выручка периода. ⁴ Учётный расход периода / та же выручка; у компонентов сетов — аналитическое распределение.</p>'
body+='<div class="note"><strong>Итог только этой выборки:</strong> исторический FC '+pct(S['historical_fc'])+'; при пересчёте текущих карт — '+pct(S['repriced_current_recipe_fc_with_zero_net'])+'. Это не подтверждает FC всей линейки: остаётся '+pct(1-S['selected_roll_revenue_coverage'])+' выручки роллов за пределами отбора. Дороговизна отдельного ролла не задаёт средний FC.</div>'
body+='<div class="note attention"><strong>Материальная цена для проверки перед проработкой:</strong> в последней проведённой накладной 17.10 сырые мидии записаны по 729,78 ₽/кг против 338,42 ₽/кг в накладной 10.10. Проверены один GUID, кг, цена с НДС и сумма строки. Отдельный SKU «мидии киви» не смешан с ним. Корректность самой первички стоит подтвердить перед утверждением карт: этот скачок заметно влияет на стоимость. В расчёте сохранена последняя учётная цена, без исправления источника.</div>'
body+='<h2 id="recipes">Действующие карты и стоимость</h2><p>Исходные названия ингредиентов сохранены. Соусы и другие полуфабрикаты раскрыты до закупаемого сырья в каждой калькуляции; рецепты заготовок находятся ниже.</p>'+''.join(cards)
body+='<h2 id="prepared">Составы заготовок</h2><p class="small">Количество приведено на одну базовую единицу выхода заготовки. Обработка и выход уже учтены при калькуляции, повторный процент потерь не добавлялся.</p>'+''.join(pfs)
body+='<h2 id="methods">Метод и проверки</h2><ul>'+notes+'</ul><p>«Крабик» и «Томаго чиз мини» отнесены к запечённым по прямому подтверждению владельца 19.10. Их исходная группа «Проработки» и отсутствие самостоятельной каталожной цены сохранены. Они вытеснили из десятки «Острый с крабом» и «Чикен чиз». «Мидии темпура» находятся в холодной группе: жареные мидии и стрипсы — начинка, внешних кляра/панировки в карте нет.</p>'
body+='<p>Выручка смешанных сетов сначала сохраняет сверенную долю линии роллов. Внутри этой доли она распределена по историческим средним оплаченным ценам отдельных роллов. Для трёх компонентов без таких цен — средняя известных компонентов соответствующего сета, с флагом оценки. Исторический food внутри сета распределён отдельно по наблюдённым сырьевым стоимостям; у двух технических компонентов также применяется явная оценка. Вся выручка и себестоимость источника сохраняются. Альтернатива распределения сильнее всего меняет выручку «Сакуры» — примерно на 4,86%; её учётный FC 22,04%→21,02%. На рейтинг количества это не влияет.</p>'
body+=tab(['Месяц','Net предприятия','Net роллов','Food роллов','Оплачено порций','Нулевых порций'],rawcontrols)
body+='<p>Независимой рекурсией проверены 97 SKU и 3 683 ветки. Родители сетов и физические компоненты не задвоены. Подтверждены все 289 непустых сочетаний SKU×месяц; отклонение выручки/food от контрольных сумм меньше копейки. Все 33 текущие карты и подготовленные разложения сверены до сырьевых листьев; ненулевых неизвестных цен, кроме воды, нет. Каталог iiko проверен 19.10; сайт вернул техническую проверку доступа, поэтому публикация и цена витрины не заявлены подтверждёнными.</p>'
body+='<h2>Файлы и следующий шаг</h2><p><a href="selection.json">Выборка и все показатели</a> · <a href="inputs.json">Агрегированные входы</a> · <a href="build_selection.py">Повторить расчёт</a> · <a href="source-manifest.json">Источники и хеши</a> · <a href="../../profit-progress.md">Журнал решений</a></p><p>Следующий шаг: проекты улучшенных карт, стоимость по одному прайсбуку и сравнение действующих/облегчённых акций. Затем взвешенный FC всей линии и пересчёт финансовой модели. Рецептуры, цены, акции и production не менялись.</p></main></html>'
(P/'report.html').write_text(body)
print('Report created: three top10tables,30fullcards, nestedrecipes, rawmaterialpricing and sourcechecks.')
